def main():
    n, a, b = map(int, input().split())
    s = input()
    k = a / b
    obtainable_categories = set()

    for category in set(s):
        positions = [i for i, c in enumerate(s) if c == category]
        m = len(positions)
        if m == 0:
            continue
        for start in range(m):
            for end in range(start, m):
                length = positions[end] - positions[start] + 1
                if k * length <= (end - start + 1):
                    obtainable_categories.add(category)
                    break

    obtainable_categories = sorted(obtainable_categories)
    print(len(obtainable_categories), ' '.join(obtainable_categories))

